 function activeUnit(side){const r=side==='player'?game?.player:game?.enemy;return r?.find(f=>f.active&&f.alive)}
 function isReady(f,t=now()){return !!f&&f.alive&&t>=f.readyAt&&t<=f.turnEnds;}
 function myReady(){return game&&!game.over&&isReady(activeUnit('player'))}
 function speedCut(f,elapsed){const remaining=Math.max(0,WINDOW-elapsed);const pct=Math.min(.38,Math.max(.08,f.speed*.022));const cut=remaining*pct;return {remaining,cut,pct};}
-function commitPlay(f,elapsed=0){const {remaining,cut,pct}=speedCut(f,elapsed);f.readyAt=now()+remaining-cut;f.turnEnds=f.readyAt+WINDOW;f.plays++;game.turn++;return {remaining,cut,pct};}
+function commitPlay(f,elapsed=0){const {remaining,cut,pct}=speedCut(f,elapsed);f.readyAt=now()+WINDOW-cut;f.turnEnds=f.readyAt+WINDOW;f.plays++;game.turn++;return {remaining,cut,pct};}
 function log(text){if(!game)return;game.log=text;game.logCount++;renderLog();}
 function renderLog(){$('logText').textContent=game?.log||'Choose your vessel to enter the arena.';$('logTurn').textContent=game?`PLAY ${String(game.turn).padStart(2,'0')}`:'—';}
 function setAction(action){if(!game||game.over)return;const f=activeUnit('player');if(!isReady(f)){toast('Your action window is not ready yet.');return}if(selectedAction===action){selectedAction=null;selectedCell=null}else{selectedAction=action;selectedCell=null}draw();updateButtons();}
 function canMoveTo(x,y,f=activeUnit('player')){if(!f||x<0||x>=GRID_W||y<0||y>=GRID_H||Math.abs(x-f.x)+Math.abs(y-f.y)!==1)return false;return ![...game.player,...game.enemy].some(o=>o.alive&&o.x===x&&o.y===y)}

