function checkResult(){if(!game||game.over)return;const p=game.player.some(f=>f.alive),e=game.enemy.some(f=>f.alive);if(!p||!e){game.over=true;$('resultTitle').textContent=p?'Victory in the Gloam':'The pact is broken';$('resultSymbol').textContent=p?'✦':'☠';$('resultText').textContent=p?'The Hollow is quiet. Your covenant survives the Bonechapel.':'Every soul in your covenant has fallen. The arena waits for another challenger.';$('resultOverlay').hidden=false;$('matchState').textContent=p?'VICTOR':'DEFEATED';}}
function draw(){if(!game)return;const board=$('board');board.innerHTML='';const p=activeUnit('player'),e=activeUnit('enemy');for(let y=0;y<GRID_H;y++)for(let x=0;x<GRID_W;x++){const tile=document.createElement('div');tile.className='tile';tile.setAttribute('role','gridcell');tile.dataset.x=x;tile.dataset.y=y;const label=document.createElement('span');label.className='tile-label';label.textContent=String.fromCharCode(65+y)+(x+1);tile.appendChild(label);if(selectedAction==='move'&&myReady()&&canMoveTo(x,y,p))tile.classList.add('movable');if(selectedAction==='attack'&&myReady()&&e&&distance({x,y},e)<=p.range&&Math.abs(x-e.x)+Math.abs(y-e.y)===0)tile.classList.add('attackable');tile.onclick=()=>onTile(x,y);board.appendChild(tile)}
 [...game.player,...game.enemy].forEach(f=>{if(!f.alive)return;const tile=board.children[f.y*GRID_W+f.x];if(!tile)return;const piece=document.createElement('div');piece.className=`piece ${f.side} ${f.active?'active':''} ${f.side==='player'&&f.index!==game.activePlayer?'reserve':''}`;piece.title=`${f.name} · ${f.hp}/${f.maxHp} HP · ${f.speed} SPD`;piece.innerHTML=`<span class="sprite" style="color:${TYPES[f.type].color}">${TYPES[f.type].icon}</span><span class="piece-base"></span>`;tile.appendChild(piece)});
 updateTop();renderRoster();renderTrait();updateButtons();}
function onTile(x,y){const f=activeUnit('player');if(!myReady()){toast('Wait for your independent action clock.');return}if(!selectedAction){const own=game.player.find(q=>q.alive&&q.x===x&&q.y===y);if(own){if(own===f){toast('Choose a play, then select a tile.')}else{const idx=game.player.indexOf(own);doSwitch(idx)}return}if(game.enemy.some(q=>q.alive&&q.x===x&&q.y===y)){setAction('attack');return}setAction('move');if(canMoveTo(x,y,f))doMove(x,y);return}if(selectedAction==='move'){if(canMoveTo(x,y,f))doMove(x,y);else toast('Move one tile to an empty square.')}else if(selectedAction==='attack'){const target=game.enemy.find(q=>q.alive&&q.x===x&&q.y===y);if(target){if(distance(f,target)<=f.range)doAttack(target);else toast(`Out of range · ${distance(f,target)} tiles away.`)}else toast('Select the rival you want to strike.')}}
function renderRoster(){if(!game)return;const root=$('playerRoster');root.innerHTML='';game.player.forEach((f,i)=>{const b=document.createElement('button');b.className=`roster-card ${f.active?'current':''} ${f.alive?'':'dead'}`;b.innerHTML=`<span class="roster-icon" style="color:${TYPES[f.type].color}">${TYPES[f.type].icon}</span><span class="roster-info"><span class="roster-name">${f.name}${f.active?' · ACTIVE':''}</span><span class="roster-stats">${f.atk} ATK · ${f.speed} SPD</span></span><span class="roster-hp">${f.alive?`${f.hp} HP`:'FALLEN'}</span>`;b.onclick=()=>{if(i===game.activePlayer)return;doSwitch(i)};root.appendChild(b)});}
function renderTrait(){const f=activeUnit('player');if(!f){$('traitHeading').textContent='Covenant broken';return}const t=TYPES[f.type];$('traitHeading').textContent=t.name;$('traitTitle').textContent=t.name+' · BLOOD ART';$('traitCopy').textContent=t.desc;let state=`${f.atk} ATK · ${f.speed} SPD`;if(f.type==='scarcity')state+=` · BANKED +${f.scarcity} next strike`;if(f.type==='cannibalism')state+=` · 12 HP returned on a kill`;$('traitState').textContent=state;$('artDesc').textContent=t.artDesc;$('artBtn').querySelector('b').textContent=t.art;}
function updateTop(){if(!game)return;const p=activeUnit('player'),e=activeUnit('enemy'),t=now();const show=(side,f)=>{const prefix=side==='player'?'p':'e';if(!f){$(`${prefix}Name`).textContent='—';return}const type=TYPES[f.type];$(`${prefix}Name`).textContent=f.name;$(`${prefix}Type`).textContent=type.short;$(`${prefix}Portrait`).textContent=type.icon;$(`${prefix}HpText`).textContent=`${f.hp} / ${f.maxHp}`;$(`${prefix}HpBar`).style.width=`${Math.max(0,100*f.hp/f.maxHp)}%`;$(`${prefix}TimerLabel`).textContent=t<f.readyAt?'NEXT TURN':'ACTION WINDOW';let remain=t<f.readyAt?f.readyAt-t:Math.max(0,f.turnEnds-t);$(`${prefix}Timer`).textContent=`${remain.toFixed(1)}s`;$(`${prefix}TimerBar`).style.width=`${Math.max(0,100*(t<f.readyAt?remain/WINDOW:remain/WINDOW))}%`;$(`${prefix}Head`).style.setProperty('--health',`${Math.max(0,100*f.hp/f.maxHp)}%`);};show('player',p);show('enemy',e);
 const ready=isReady(p,t);$('turnStatus').textContent=ready?'YOUR TURN — MAKE A PLAY':t<p.readyAt?'Your clock is winding…':'Your action window expired';$('bigTimer').textContent=p?`${(t<p.readyAt?p.readyAt-t:Math.max(0,p.turnEnds-t)).toFixed(1)}s`:'—';$('bigTimer').style.color=ready?'#e4be7c':'#b8aab0';$('coolFill').style.width=p?`${100*(t<p.readyAt?1-(p.readyAt-t)/WINDOW:(p.turnEnds-t)/WINDOW)}%`:'0%';$('timerNote').textContent=ready?'One play before your window closes. Speed trims the next wait immediately.':`Your next play is independent of the rival's clock.`;$('matchState').textContent=ready?'YOUR WINDOW IS OPEN':'DUEL IN PROGRESS';$('arenaStatus').textContent=ready?'YOUR PLAY · CHOOSE WISELY':'THE CLOCKS RUN APART';}

