 const ready=isReady(p,t);$('turnStatus').textContent=ready?'YOUR TURN — MAKE A PLAY':t<p.readyAt?'Your clock is winding…':'Your action window expired';$('bigTimer').textContent=p?`${(t<p.readyAt?p.readyAt-t:Math.max(0,p.turnEnds-t)).toFixed(1)}s`:'—';$('bigTimer').style.color=ready?'#e4be7c':'#b8aab0';$('coolFill').style.width=p?`${100*(t<p.readyAt?1-(p.readyAt-t)/WINDOW:(p.turnEnds-t)/WINDOW)}%`:'0%';$('timerNote').textContent=ready?'One play before your window closes. Speed trims the next wait immediately.':`Your next play is independent of the rival's clock.`;$('matchState').textContent=ready?'YOUR WINDOW IS OPEN':'DUEL IN PROGRESS';$('arenaStatus').textContent=ready?'YOUR PLAY · CHOOSE WISELY':'THE CLOCKS RUN APART';}
function updateButtons(){const ready=myReady();document.querySelectorAll('.action-btn').forEach(b=>b.disabled=!ready);if(game){const f=activeUnit('player');$('switchBtn').disabled=!ready||!game.player.some((x,i)=>i!==game.activePlayer&&x.alive);$('artBtn').disabled=!ready||(f.type==='insatiability'&&f.speed<=2)||(f.type==='cannibalism'&&f.hp<=8)}}
function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1500)}
function aiPlay(t){if(!game||game.over)return;const f=activeUnit('enemy'),target=activeUnit('player');if(!f||!target)return;if(!isReady(f,t)){if(t>f.turnEnds){f.readyAt=t+WINDOW-Math.min(WINDOW*.35,WINDOW*f.speed*.022);f.turnEnds=f.readyAt+WINDOW;log(`${f.name} lets its window pass; its clock begins again.`)}return}
 const elapsed=Math.max(0,WINDOW-(f.turnEnds-t)),remaining=Math.max(0,WINDOW-elapsed);if(f.hp<32&&game.enemy.some(o=>o.alive&&!o.active)&&Math.random()<.58){const next=game.enemy.find(o=>o.alive&&!o.active);const old=f;old.active=false;next.active=true;next.x=old.x;next.y=old.y;const r=commitPlay(next,elapsed);log(`${old.name} retreats. ${next.name} takes the field.`);return}
