ion:column;gap:11px}.sidepanel{border:1px solid var(--line);background:linear-gradient(145deg,#201a22,#18141b);padding:13px}.panel-kicker{color:#a48d91;font:9px 'DM Mono',monospace;letter-spacing:1.4px;margin-bottom:8px}.panel-title{font:17px 'IM Fell English SC',serif;letter-spacing:.5px}.turn-card{border-color:#5a4148}.turn-row{display:flex;align-items:center;justify-content:space-between;margin-top:10px}.turn-label{font-size:11px;color:#c9b9b6}.big-timer{font:23px 'DM Mono',monospace;color:#e3b46e}.cool-track{height:4px;background:#382e37;margin-top:8px}.cool-fill{height:100%;width:0;background:linear-gradient(90deg,#ad706f,#e2b46e);transition:width .15s linear}.timer-note{font:9px 'DM Mono',monospace;color:#968890;margin-top:7px}.roster{display:flex;flex-direction:column;gap:7px;margin-top:10px}.roster-card{display:flex;align-items:center;gap:8px;background:#17131a;border:1px solid #342a35;padding:7px 8px;cursor:pointer;text-align:left;width:100%;transition:border .15s,background .15s}.roster-card:hover{border-color:#79564f}.roster-card.current{border-color:#a77664;background:#2c2024}.roster-card.dead{opacity:.42;cursor:not-allowed}.roster-icon{font-size:20px;width:25px;text-align:center}.roster-info{flex:1}.roster-name{font:12px 'IM Fell English SC',serif}.roster-stats{font:8px 'DM Mono',monospace;color:#93858e;margin-top:3px}.roster-hp{font:9px 'DM Mono',monospace;color:#d4a19a}.trait{padding:10px;background:#18141b;border-left:2px solid #b87d66;margin-top:10px}.trait-title{font:11px 'IM Fell English SC',serif;color:#e0ba8d}.trait-copy{font-size:10px;line-height:1.45;color:#a89ba0;margin-top:4px}.trait-state{font:9px 'DM Mono',monospace;color:#b7a59a;margin-top:7px}.actions{display:grid;grid-template-columns:repeat(2,1fr);gap:7px;margin-top:auto}.action-btn{border:1px solid #51404a;background:#241d25;padding:10px 8px;text-align:left;min-height:57px;transition:all .12s;position:relative}.action-btn:hover:not(:disabled){background:#35252b;border-color:#a67465;transform:translateY(-1px)}.action-btn:disabled{opacity:.38;cursor:not-allowed}.action-btn .key{position:absolute;right:7px;top:6px;color:#8c7d85;font:8px 'DM Mono',monospace;border:1px solid #51434c;padding:1px 4px}.action-btn b{display:block;font:13px 'IM Fell English SC',serif;color:#e5d7c5}.action-btn small{display:block;font:9px 'DM Mono',monospace;color:#9d8e96;margin-top:4px}.action-btn.primary{border-color:#995b54;background:#38252a}.action-btn.primary b{color:#f1bf99}.action-btn.special b{color:#d8b27b}.hint{font:9px 'DM Mono',monospace;line-height:1.6;color:#887d85;padding:2px 3px}.hint em{color:#c09f72;font-style:normal}.bottomline{display:flex;justify-content:space-between;gap:12px;padding:11px 3px 0;color:#756b74;font:9px 'DM Mono',monospace}.bottomline span:last-child{text-align:right}.modal-backdrop{position:fixed;inset:0;background:#0a080bd9;z-index:20;display:grid;place-items:center;padding:18px;backdrop-filter:blur(4px)}.modal{max-width:650px;width:100%;border:1px solid #70505a;background:linear-gradient(140deg,#251b24,#151118);padding:26px;box-shadow:0 20px 70px #000b}.modal-kicker{color:#ca9b70;font:10px 'DM Mono',monospace;letter-spacing:2px}.modal h1{font:38px 'IM Fell English SC',serif;font-weight:400;letter-spacing:2px;margin:6px 0 4px}.modal p{font-size:12px;color:#aa9ca2;line-height:1.6;margin:0 0 17px}.choose-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.choose-card{background:#19151c;border:1px solid #483842;padding:13px 10px;cursor:pointer;text-align:left;transition:all .15s;min-height:126px}.choose-card:hover,.choose-card.chosen{border-color:#c99568;background:#302128;box-shadow:inset 0 0 20px #a5673222}.choose-card .emblem{font-size:29px;display:block;margin-bottom:8px}.choose-card strong{display:block;font:14px 'IM Fell English SC',serif;color:#e4cda9}.choose-card span{display:block;font-size:10px;color:#a698a0;line-height:1.4;margin-top:5px}.choose-stats{font:9px 'DM Mono',monospace!important;color:#ca9a72!important;margin-top:8px!important}.modal-actions{display:flex;align-items:center;justify-content:space-between;margin-top:18px;gap:10px}.modal-note{font:9px 'DM Mono',monospace;color:#8c7c84}.start-btn{border:1px solid #bd8065;background:linear-gradient(110deg,#733d3d,#563139);padding:11px 20px;font:12px 'DM Mono',monospace;letter-spacing:1px;color:#f5dec0}.start-btn:hover{filter:brightness(1.2)}.overlay{position:fixed;inset:0;background:#09070bdc;z-index:15;display:grid;place-items:center;padding:18px;backdrop-filter:blur(3px)}.result-card{text-align:center;border:1px solid #75505a;background:#211820;padding:30px;max-width:390px;width:100%;box-shadow:0 20px 70px #000}.result-symbol{font-size:44px;color:#d6a66e}.result-card h2{font:30px 'IM Fell English SC',serif;margin:8px 0}.result-card p{color:#aaa0a4;font-size:12px;line-height:1.6}.result-card button{margin-top:12px}.toast{position:fixed;z-index:30;top:18px;left:50%;transform:translate(-50%,-20px);padding:9px 14px;border:1px solid #9c624e;background:#2c2026;color:#f0d7b6;font:11px 'DM Mono',monospace;opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes idle{50%{transform:translateY(-3px)}}@keyframes floatup{0%{opacity:1;transform:translate(-50%,0)}100%{opacity:0;transform:translate(-50%,-42px)}}
@media(max-width:980px){.layout{grid-template-columns:minmax(0,1fr) 235px;gap:9px}.app{padding:12px}.board{grid-template-rows:repeat(5,minmax(58px,1fr))}.sidepanel{padding:10px}.duelheads{gap:7px}.combatant{padding:10px}.arena-cap{height:26px}}
@media(max-width:720px){.app{padding:10px}.layout{grid-template-columns:1fr}.sidebar{display:grid;grid-template-columns:1fr 1fr;align-items:start}.sidebar .actions{grid-column:1/-1;grid-row:1}.sidebar .hint{grid-column:1/-1}.board-wrap{padding:7px}.board{gap:2px;grid-template-rows:repeat(5,minmax(48px,1fr));aspect-ratio:1.38}.tile-label{font-size:7px}.piece{transform:scale(.8)}.piece.reserve{transform:scale(.65)}.bottomline{font-size:8px}.duelheads{gap:6px}.portrait{width:30px;height:30px}.fighter-name{font-size:14px}.type-tag{font-size:7px}.combatant{padding:8px}.combatant .vitals{font-size:8px}.topbar{padding-bottom:10px}.brand-title{font-size:19px}.round-chip{font-size:8px;padding:6px}.sidepanel.turn-card{grid-column:1/-1}.sidepanel.roster-panel{grid-row:2}.sidepanel.trait-panel{grid-row:2}}
@media(max-width:430px){.brand-sub{font-size:7px}.top-right{gap:6px}.round-chip{padding:5px}.board{grid-template-rows:repeat(5,minmax(41px,1fr));aspect-ratio:1.26}.piece{transform:scale(.68)}.piece.reserve{transform:scale(.57)}.tile:before{display:none}.modal{padding:18px}.modal h1{font-size:30px}.choose-grid{gap:5px}.choose-card{padding:9px 7px;min-height:130px}.choose-card strong{font-size:12px}.choose-card span{font-size:9px}.choose-card .emblem{font-size:24px}.actions{gap:5px}.action-btn{padding:8px 6px;min-height:52px}.action-btn b{font-size:12px}.action-btn small{font-size:8px}}
