</head>
<body>
<div class="app">
<header class="topbar"><div class="brand"><div class="sigil"><span>✦</span></div><div><div class="brand-title">Ashen Pact</div><div class="brand-sub">THE GLOAM ARENA · A DUEL OF WILLS</div></div></div><div class="top-right"><span class="round-chip" id="matchState">AWAITING CHALLENGER</span><button class="sound-toggle" id="restartTop">↻ &nbsp;NEW DUEL</button></div></header>
<main class="layout">
<section class="battle"><div class="duelheads">
<div class="combatant" id="playerHead"><div class="head-row"><div class="portrait" id="pPortrait">✦</div><div class="who"><div class="name-line"><span class="fighter-name" id="pName">Wanderer</span><span class="type-tag" id="pType">UNBOUND</span></div><div class="vitals"><span>VITALITY</span><span id="pHpText">— / —</span></div><div class="hp-track"><div class="hp-fill" id="pHpBar"></div></div><div class="timerline"><span id="pTimerLabel">NEXT TURN</span><div class="timer-bar"><i id="pTimerBar"></i></div><span id="pTimer">—</span></div></div></div></div>
<div class="combatant enemy" id="enemyHead"><div class="head-row"><div class="portrait" id="ePortrait">☠</div><div class="who"><div class="name-line"><span class="fighter-name" id="eName">The Hollow</span><span class="type-tag" id="eType">RIVAL</span></div><div class="vitals"><span>VITALITY</span><span id="eHpText">— / —</span></div><div class="hp-track"><div class="hp-fill" id="eHpBar"></div></div><div class="timerline"><span id="eTimerLabel">NEXT TURN</span><div class="timer-bar"><i id="eTimerBar"></i></div><span id="eTimer">—</span></div></div></div></div></div>
<div class="arena"><div class="arena-cap"><span>▧ &nbsp;BONECHAPEL · <strong>ASHEN FLOOR</strong></span><span id="arenaStatus">A WARD OF OLD STONE</span></div><div class="board-wrap"><div class="board" id="board" role="grid" aria-label="Battle grid"></div></div><div class="combat-log"><span class="log-icon">✧</span><span class="log-text" id="logText">Choose your vessel to enter the arena.</span><span class="log-turn" id="logTurn">—</span></div></div>
<div class="bottomline"><span>▲ MOVE &nbsp;·&nbsp; ✦ STRIKE &nbsp;·&nbsp; ⟳ SWITCH &nbsp;·&nbsp; ◆ ART</span><span>THE CLOCKS RUN APART. YOUR CHOICE IS YOURS.</span></div></section>
<aside class="sidebar">
<div class="sidepanel turn-card"><div class="panel-kicker">YOUR ACTION WINDOW</div><div class="turn-row"><span class="turn-label" id="turnStatus">Waiting for the duel…</span><span class="big-timer" id="bigTimer">—</span></div><div class="cool-track"><div class="cool-fill" id="coolFill"></div></div><div class="timer-note" id="timerNote">An independent 10-second clock for each soul.</div></div>
<div class="sidepanel roster-panel"><div class="panel-kicker">YOUR COVENANT · ACTIVE SOUL</div><div class="panel-title">The Bound</div><div class="roster" id="playerRoster"></div></div>
<div class="sidepanel trait-panel"><div class="panel-kicker">BLOOD PACT</div><div class="panel-title" id="traitHeading">Choose a vessel</div><div class="trait" id="traitBox"><div class="trait-title" id="traitTitle">Three hungers. One arena.</div><div class="trait-copy" id="traitCopy">Every play takes a turn. Your speed cuts a single portion from your remaining clock immediately—never more than once per turn.</div><div class="trait-state" id="traitState">Select an archetype to begin.</div></div></div>
<div class="actions" id="actions"><button class="action-btn" id="moveBtn" data-action="move"><span class="key">1</span><b>Move</b><small>Step one tile</small></button><button class="action-btn primary" id="attackBtn" data-action="attack"><span class="key">2</span><b>Strike</b><small>Attack within range</small></button><button class="action-btn special" id="artBtn" data-action="art"><span class="key">3</span><b>Blood Art</b><small id="artDesc">Archetype power</small></button><button class="action-btn" id="switchBtn" data-action="switch"><span class="key">4</span><b>Switch</b><small>Change active soul</small></button></div>
<div class="hint">Click a tile or use <em>WASD / arrows</em> to move. <em>1–4</em> selects a play. Opponent acts on its own clock.</div>
</aside></main></div>
<div class="modal-backdrop" id="setupModal"><div class="modal"><div class="modal-kicker">THE COVENANT IS SEALED IN BLOOD</div><h1>Choose your vessel</h1><p>Three condemned souls. One active fighter at a time. Your fallen enemies will not wait for your turn.</p><div class="choose-grid" id="chooseGrid"></div><div class="modal-actions"><span class="modal-note">Both sides begin together. Independent clocks. No alternating turns.</span><button class="start-btn" id="beginBtn">ENTER THE ARENA &nbsp;→</button></div></div></div>
<div class="overlay" id="resultOverlay" hidden><div class="result-card"><div class="result-symbol" id="resultSymbol">✧</div><h2 id="resultTitle">Duel ended</h2><p id="resultText"></p><button class="start-btn" id="againBtn">FIGHT AGAIN &nbsp;↻</button></div></div>
<div class="toast" id="toast"></div>
<script>
(() => {
'use strict';
const TYPES={
  insatiability:{name:'Insatiability',short:'INSATIABLE',icon:'♨',hp:112,atk:15,speed:7,range:1,color:'#e39a71',desc:'Consumes speed to grow stronger. Each Blood Art permanently trades 1 speed for +3 attack.',art:'Devour',artDesc:'Lose 1 speed · gain +3 ATK'},
  scarcity:{name:'Scarcity',short:'SCARCE',icon:'◈',hp:98,atk:17,speed:10,range:2,color:'#c6a9dc',desc:'The more time left when you act, the more power you bank for your next turn. Up to +7 damage.',art:'Hoard',artDesc:'Bank a bonus from time left'},
  cannibalism:{name:'Cannibalism',short:'CANNIBAL',icon:'☠',hp:124,atk:13,speed:8,range:1,color:'#bd7788',desc:'Spend your own vitality to feed a vicious close-range strike. A kill restores 12 HP.',art:'Feast',artDesc:'Pay 8 HP · strike for +12'}
};
const GRID_W=7,GRID_H=5,WINDOW=10;
let selectedType='insatiability',game=null,selectedAction=null,selectedCell=null,lastFrame=0,toastTimer;
const $=id=>document.getElementById(id);
const now=()=>performance.now()/1000;
function makeFighter(type,side,index){const t=TYPES[type];return {type,name:t.name,hp:t.hp,maxHp:t.hp,atk:t.atk,speed:t.speed,baseSpeed:t.speed,range:t.range,side,index,x:side==='player'?1:5,y:index===0?2:(index===1?1:3),alive:true,readyAt:0,turnEnds:0,active:index===0,scarcity:0,plays:0,guard:false};}
function buildRoster(activeType,side){const types=side==='player'?[activeType,...Object.keys(TYPES).filter(t=>t!==activeType)]:['scarcity','cannibalism','insatiability'];return types.map((type,i)=>makeFighter(type,side,i));}
function setup(){ $('chooseGrid').innerHTML='';Object.entries(TYPES).forEach(([key,t])=>{const b=document.createElement('button');b.className='choose-card'+(key===selectedType?' chosen':'');b.innerHTML=`<span class="emblem" style="color:${t.color}">${t.icon}</span><strong>${t.name}</strong><span>${t.desc}</span><span class="choose-stats">${t.hp} HP · ${t.atk} ATK · ${t.speed} SPD</span>`;b.onclick=()=>{selectedType=key;setup()};$('chooseGrid').appendChild(b)});}
function startGame(){
 game={started:true,over:false,start:now(),turn:0,player:buildRoster(selectedType,'player'),enemy:buildRoster(selectedType,'enemy'),activePlayer:0,activeEnemy:0,log:'The bell tolls. Both souls enter the Bonechapel.',logCount:0,toast:null};
 game.player[0].x=1;game.player[0].y=2;game.enemy[0].x=5;game.enemy[0].y=2;
 game.enemy.forEach((f,i)=>{f.type=['scarcity','cannibalism','insatiability'][i];const t=TYPES[f.type];f.name=['The Hollow','Grin-Eater','Ash Votary'][i];f.hp=f.maxHp=t.hp;f.atk=t.atk;f.speed=t.speed;f.baseSpeed=t.speed;f.range=t.range;});
 game.player.forEach((f,i)=>{f.x=i===0?1:-1;f.y=i===0?2:-1}); game.enemy.forEach((f,i)=>{f.x=i===0?5:-1;f.y=i===0?2:-1});
 game.player[0].active=true;game.enemy[0].active=true;game.player[0].turnEnds=game.enemy[0].turnEnds=game.start+WINDOW;
 $('setupModal').hidden=true;$('resultOverlay').hidden=true;selectedAction=null;selectedCell=null;updateTop();updateButtons();renderRoster();renderTrait();draw();renderLog();requestAnimationFrame(loop);
}
function activeUnit(side){const r=side==='player'?game?.player:game?.enemy;return r?.find(f=>f.active&&f.alive)}
function isReady(f,t=now()){return !!f&&f.alive&&t>=f.readyAt&&t<=f.turnEnds;}
function myReady(){return game&&!game.over&&isReady(activeUnit('player'))}
function speedCut(f,elapsed){const remaining=Math.max(0,WINDOW-elapsed);const pct=Math.min(.38,Math.max(.08,f.speed*.022));const cut=remaining*pct;return {remaining,cut,pct};}
