 else {if(f.hp<=8){toast('Not enough vitality to pay the blood price.');return}f.hp-=8;const foes=game.enemy.filter(o=>o.alive&&distance(f,o)<=1);f.guard=false;if(foes.length){const target=foes[0];const damage=f.atk+12;target.hp=Math.max(0,target.hp-damage);target.alive=target.hp>0;if(!target.alive){target.active=false;f.hp=Math.min(f.maxHp,f.hp+12);activateNext('enemy')}floatAt(target.x,target.y,`−${damage}`);log(`${f.name} pays 8 HP to feast on ${target.name}: ${damage} damage${!target.alive?' — slain, +12 HP!':'!'}`)}else{f.hp=Math.min(f.maxHp,f.hp+16);log(`${f.name} tears into itself: −8 HP, then regains 16 HP from the frenzy.`)}const r=commitPlay(f,elapsed);if(f.hp<=0){f.alive=false;f.active=false;activateNext('player')}}
