function doSwitch(index){const f=activeUnit('player'),next=game.player[index];if(!myReady()||!next||!next.alive||next===f)return;const elapsed=WINDOW-Math.max(0,f.turnEnds-now());f.active=false;next.active=true;next.x=f.x;next.y=f.y;f.x=-1;f.y=-1;const r=commitPlay(next,elapsed);log(`${f.name} yields the field to ${next.name}. The clock sheds ${r.cut.toFixed(1)}s.`);selectedAction=null;draw();updateTop();updateButtons();renderRoster();renderTrait();}
function activateNext(side){const roster=side==='player'?game.player:game.enemy;const old=side==='player'?game.activePlayer:game.activeEnemy;const next=roster.findIndex(f=>f.alive);if(side==='player')game.activePlayer=next;else game.activeEnemy=next;if(next>=0){roster.forEach((f,i)=>f.active=i===next);const n=roster[next];const occupied=(x,y)=>[...game.player,...game.enemy].some(o=>o.alive&&o!==n&&o.x===x&&o.y===y);let sx=side==='player'?0:6,sy=2;if(occupied(sx,sy)){for(const [dx,dy] of [[0,-1],[0,1],[side==='player'?1:-1,0],[0,-2],[0,2]]){const nx=sx+dx,ny=2+dy;if(ny>=0&&ny<GRID_H&&!occupied(nx,ny)){sx=nx;sy=ny;break}}}n.x=sx;n.y=sy;log(`${n.name} enters the fray!`)} }
