function onTile(x,y){const f=activeUnit('player');if(!myReady()){toast('Wait for your independent action clock.');return}if(!selectedAction){const own=game.player.find(q=>q.alive&&q.x===x&&q.y===y);if(own){if(own===f){toast('Choose a play, then select a tile.')}else{const idx=game.player.indexOf(own);doSwitch(idx)}return}if(game.enemy.some(q=>q.alive&&q.x===x&&q.y===y)){setAction('attack');return}setAction('move');if(canMoveTo(x,y,f))doMove(x,y);return}if(selectedAction==='move'){if(canMoveTo(x,y,f))doMove(x,y);else toast('Move one tile to an empty square.')}else if(selectedAction==='attack'){const target=game.enemy.find(q=>q.alive&&q.x===x&&q.y===y);if(target){if(distance(f,target)<=f.range)doAttack(target);else toast(`Out of range · ${distance(f,target)} tiles away.`)}else toast('Select the rival you want to strike.')}}
function renderRoster(){if(!game)return;const root=$('playerRoster');root.innerHTML='';game.player.forEach((f,i)=>{const b=document.createElement('button');b.className=`roster-card ${f.active?'current':''} ${f.alive?'':'dead'}`;b.innerHTML=`<span class="roster-icon" style="color:${TYPES[f.type].color}">${TYPES[f.type].icon}</span><span class="roster-info"><span class="roster-name">${f.name}${f.active?' · ACTIVE':''}</span><span class="roster-stats">${f.atk} ATK · ${f.speed} SPD</span></span><span class="roster-hp">${f.alive?`${f.hp} HP`:'FALLEN'}</span>`;b.onclick=()=>{if(i===game.activePlayer)return;doSwitch(i)};root.appendChild(b)});}
function renderTrait(){const f=activeUnit('player');if(!f){$('traitHeading').textContent='Covenant broken';return}const t=TYPES[f.type];$('traitHeading').textContent=t.name;$('traitTitle').textContent=t.name+' · BLOOD ART';$('traitCopy').textContent=t.desc;let state=`${f.atk} ATK · ${f.speed} SPD`;if(f.type==='scarcity')state+=` · BANKED +${f.scarcity} next strike`;if(f.type==='cannibalism')state+=` · 12 HP returned on a kill`;$('traitState').textContent=state;$('artDesc').textContent=t.artDesc;$('artBtn').querySelector('b').textContent=t.art;}
